import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listMyHomeSpacesHandler } from "../handlers/listMyHomeSpacesHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listMyHomeSpacesHandler>>;

export function useListMyHomeSpaces(
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listMyHomeSpaces", bookmark],
    queryFn: () => listMyHomeSpacesHandler(bookmark),
    ...options,
  });
}
